{
  "name": "pentest-cli",
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "init": "node cli/init.js",
    "recon": "node cli/recon.js",
    "vuln": "node cli/vuln.js",
    "exploit": "node cli/exploit.js",
    "analyze": "node cli/analyze.js",
    "report": "node cli/report.js",
    "cli": "node cli/cli.js",
    "test": "node test/index.js"
  },
  "dependencies": {
    "@playwright/test": "^1.45.0",
    "chalk": "^5.3.0",
    "open": "^10.1.0",
    "readline-sync": "^1.4.10",
    "yaml": "^2.5.0"
  },
  "devDependencies": {
    "@types/node": "^22.19.0",
    "typescript": "^5.5.0"
  }
}

